			"  entire clone /gh/entirehq/entire-api --cluster aws-us-east-2.entire.io\n" +
			"  entire clone entire://aws-us-east-2.entire.io/gh/entirehq/entire-api",
		Args: cobra.RangeArgs(1, 2),
